content.content:
1	/**
2	 * T2.5 poll reconciliation.
3	 *
4	 * Webhooks get dropped, so polling is the safety net that makes a lost
5	 * delivery survivable. A dispatched run carries `poll_after` and the tick
6	 * advances it by re-fetching the authoritative call. Follow-up crosses tick
7	 * boundaries rather than looping, because a free Edge Function allows 150
8	 * seconds of wall clock per request.
9	 *
10	 * Whichever of the webhook and the poll arrives first wins. Every write here
11	 * is a conditional PATCH that only matches a still-pending run, so the second
12	 * arrival changes nothing and records nothing.
13	 *
14	 * This module sets a terminal `state` and deliberately leaves `completed_at`
15	 * null. The tick's finaliser owns `completed_at` and the ingestion that
16	 * follows, because `terminalRuns()` selects terminal runs with a null
17	 * `completed_at`, and a poll must not shortcut that.
18	 */
19	
20	import type { CalleDeps } from "./calle.ts";
21	import { recordCallEvent } from "./events.ts";
22	import type { CallStatus, CallTaskFixture } from "./fixtures.ts";
23	
24	/** The first follow-up is set by dispatch. Each pass after that waits ten. */
25	export const POLL_INTERVAL_MS = 10_000;
26	
27	/**
28	 * A run the provider never resolves is worse than a failed one, because it is
29	 * invisible. Give up well past the 140 seconds a real call took, and name the
30	 * reason on the run so an operator sees where it stopped.
31	 */
32	export const POLL_GIVE_UP_MS = 15 * 60_000;
33	
34	/** The terminal states the provider can report, mapped onto `call_runs.state`. */
35	export type TerminalState = "completed" | "failed" | "canceled";
36	
37	export type PollableRun = {
38	  id: string;
39	  state: string;
40	  poll_after: string | null;
41	};
42	
43	type RunRow = {
44	  id: string;
45	  state: string;
46	  calle_call_id: string | null;
47	  dispatched_at: string | null;
48	  poll_after: string | null;
49	  created_at: string;
50	};
51	
52	const PENDING_STATES = "in.(dispatched,awaiting_result)";
53	
54	function restUrl(base: string, path: string, query = ""): string {
55	  return `${base.replace(/\/+$/, "")}/rest/v1/${path}${query ? `?${query}` : ""}`;
56	}
57	
58	function serviceHeaders(key: string, prefer?: string): HeadersInit {
59	  const headers: Record<string, string> = {
60	    apikey: key,
61	    authorization: `Bearer ${key}`,
62	    "content-type": "application/json",
63	  };
64	  if (prefer) headers.prefer = prefer;
65	  return headers;
66	}
67	
68	export function terminalStateFor(status: CallStatus): TerminalState | null {
69	  if (status === "completed") return "completed";
70	  if (status === "failed") return "failed";
71	  if (status === "canceled") return "canceled";
72	  return null;
73	}
74	
75	/**
76	 * Re-fetches one authoritative call. It carries no run-state side effect, so
77	 * the tick's finaliser can reuse it for a run the webhook already terminalised.
78	 */
79	export async function fetchCall(
80	  callId: string,
81	  deps: CalleDeps,
82	): Promise<CallTaskFixture> {
83	  if (!callId) throw new Error("poll requires a CALL-E call id");
84	  const response = await deps.fetch(
85	    `${deps.calleApiBase.replace(/\/+$/, "")}/v1/calls/${encodeURIComponent(callId)}`,
86	    { headers: { authorization: `Bearer ${deps.calleApiKey}` } },
87	  );
88	  if (!response.ok) throw new Error(`CALL-E re-fetch returned HTTP ${response.status}`);
89	  const value: unknown = await response.json();
90	  if (typeof value !== "object" || value === null) {
91	    throw new Error("CALL-E re-fetch returned no call task");
92	  }
93	  const call = value as Partial<CallTaskFixture>;
94	  if (typeof call.id !== "string" || typeof call.status !== "string") {
95	    throw new Error("CALL-E re-fetch response missing id or status");
96	  }
97	  if (call.id !== callId) {
98	    throw new Error(`CALL-E re-fetch returned ${call.id} for ${callId}`);
99	  }
100	  return call as CallTaskFixture;
101	}
102	
103	async function readRun(deps: CalleDeps, runId: string): Promise<RunRow | null> {
104	  const query = new URLSearchParams({
105	    select: "id,state,calle_call_id,dispatched_at,poll_after,created_at",
106	    id: `eq.${runId}`,
107	    limit: "1",
108	  });
109	  const response = await deps.fetch(restUrl(deps.apiUrl, "call_runs", query.toString()), {
110	    headers: serviceHeaders(deps.serviceRoleKey),
111	  });
112	  if (!response.ok) throw new Error("call_runs poll read failed");
113	  const rows = await response.json() as RunRow[];
114	  return rows[0] ?? null;
115	}
116	
117	/**
118	 * Applies a patch only while the run is still pending, and reports whether
119	 * this caller was the one that won. Returning the representation is what makes
120	 * the loss observable rather than assumed.
121	 */
122	async function patchPendingRun(
123	  deps: CalleDeps,
124	  runId: string,
125	  patch: Record<string, unknown>,
126	): Promise<boolean> {
127	  const query = new URLSearchParams({ id: `eq.${runId}`, state: PENDING_STATES });
128	  const response = await deps.fetch(restUrl(deps.apiUrl, "call_runs", query.toString()), {
129	    method: "PATCH",
130	    headers: serviceHeaders(deps.serviceRoleKey, "return=representation"),
131	    body: JSON.stringify(patch),
132	  });
133	  if (!response.ok) throw new Error("call_runs poll update failed");
134	  const rows = await response.json() as unknown[];
135	  return Array.isArray(rows) && rows.length === 1;
136	}
137	
138	function failure(code: string, message: string): Record<string, string> {
139	  return { failure_code: code, failure_message: message };
140	}
141	
142	async function reschedule(
143	  deps: CalleDeps,
144	  runId: string,
145	  callId: string | null,
146	  detail: Record<string, string | number | boolean | null>,
147	): Promise<void> {
148	  const pollAfter = new Date(deps.now().getTime() + POLL_INTERVAL_MS).toISOString();
149	  const won = await patchPendingRun(deps, runId, { poll_after: pollAfter });
150	  if (!won) return;
151	  await recordCallEvent(runId, "polled", { calle_call_id: callId, ...detail }, deps);
152	}
153	
154	/**
155	 * Advances one pending run by one poll pass. A transport failure, a provider
156	 * error or an unparseable body reschedules the next pass instead of throwing,
157	 * so one poisoned run cannot fail the whole tick.
158	 */
159	export async function pollRun(run: PollableRun, deps: CalleDeps): Promise<void> {
160	  const current = await readRun(deps, run.id);
161	  // The webhook may have terminalised this run between the tick's read and
162	  // this call. That is the race, and losing it is a no-op.
163	  if (!current || current.state !== "dispatched" && current.state !== "awaiting_result") {
164	    return;
165	  }
166	
167	  if (!current.calle_call_id) {
168	    const won = await patchPendingRun(deps, run.id, {
169	      state: "failed",
170	      disposition: "not_answered",
171	      calle_failure: failure("poll_unavailable", "run has no CALL-E call id to poll"),
172	    });
173	    if (won) {
174	      await recordCallEvent(
175	        run.id,
176	        "polled",
177	        { calle_call_id: null, state: "failed", failure_reason: "run has no CALL-E call id to poll" },
178	        deps,
179	      );
180	    }
181	    return;
182	  }
183	
184	  // The window runs from a clock that never moves. `poll_after` cannot stand
185	  // in for a missing `dispatched_at`, because every pass rewrites it and the
186	  // deadline would slide forever. `created_at` is set once and never null.
187	  const windowStart = current.dispatched_at ?? current.created_at;
188	  const deadline = windowStart ? new Date(windowStart).getTime() + POLL_GIVE_UP_MS : NaN;
189	  const overdue = Number.isFinite(deadline) && deps.now().getTime() > deadline;
190	
191	  // An overdue run still asks CALL-E first. Only the re-fetch may decide a
192	  // state, so a call that completed late must land as completed, not unanswered.
193	  const giveUp = async (message: string, outcome: string): Promise<void> => {
194	    const won = await patchPendingRun(deps, run.id, {
195	      state: "failed",
196	      disposition: "not_answered",
197	      calle_failure: failure("poll_timeout", message),
198	    });
199	    if (won) {
200	      await recordCallEvent(
201	        run.id,
202	        "polled",
203	        { calle_call_id: current.calle_call_id, state: "failed", failure_reason: "poll_timeout", outcome },
204	        deps,
205	      );
206	    }
207	  };
208	
209	  let call: CallTaskFixture;
210	  try {
211	    call = await fetchCall(current.calle_call_id, deps);
212	  } catch (error) {
213	    const reason = error instanceof Error ? error.message : "unknown error";
214	    // Past the window a failing re-fetch also gives up. Retrying forever would
215	    // unbound the window, and the message keeps the re-fetch error visible.
216	    if (overdue) {
217	      await giveUp(`CALL-E re-fetch failed past the give-up window: ${reason}`, "refetch_failed");
218	      return;
219	    }
220	    await reschedule(deps, run.id, current.calle_call_id, {
221	      state: current.state,
222	      outcome: "refetch_failed",
223	      failure_reason: reason,
224	    });
225	    return;
226	  }
227	
228	  const terminal = terminalStateFor(call.status);
229	  if (!terminal) {
230	    if (overdue) {
231	      await giveUp("CALL-E never reported a terminal state", "pending");
232	      return;
233	    }
234	    await reschedule(deps, run.id, call.id, { state: call.status, outcome: "pending" });
235	    return;
236	  }
237	
238	  const failureCode = call.failure_code;
239	  const patch: Record<string, unknown> = {
240	    state: terminal,
241	    calle_confidence: call.completion_confidence,
242	    calle_failure: failureCode ? failure(failureCode, call.failure_message ?? "") : null,
243	    poll_after: null,
244	  };
245	  const won = await patchPendingRun(deps, run.id, patch);
246	  if (!won) return;
247	  await recordCallEvent(
248	    run.id,
249	    "polled",
250	    { calle_call_id: call.id, state: terminal, outcome: "terminal" },
251	    deps,
252	  );
253	}
254	
255	const testFn = (Deno as { test?: (name: string, fn: () => void | Promise<void>) => void }).test;
256	if (typeof testFn === "function") {
257	  const NOW = new Date("2026-09-13T10:00:00.000Z");
258	  const RUN = "11111111-1111-4111-8111-111111111111";
259	  const CALL = "call_poll_1";
260	
261	  type Seen = { method: string; url: string; body: unknown };
262	
263	  const depsFor = (
264	    fetchImpl: typeof fetch,
265	    now: Date = NOW,
266	  ): CalleDeps => ({
267	    apiUrl: "https://orma-api.test",
268	    serviceRoleKey: "service-key",
269	    calleApiBase: "https://api.call-e.test",
270	    calleApiKey: "calle-key",
271	    webhookUrl: "https://orma-api.test/functions/v1/calle-webhook/secret",
272	    fetch: fetchImpl,
273	    now: () => now,
274	  });
275	
276	  /** Every mock branches on method and path and throws on anything else, so no
277	   * test can reach a real service and no unexpected call can pass unnoticed. */
278	  const driver = (options: {
279	    run: Partial<RunRow> & { id: string; state: string };
280	    call?: unknown;
281	    callStatus?: number;
282	    patchWins?: boolean;
283	    callThrows?: boolean;
284	  }) => {
285	    const seen: Seen[] = [];
286	    const events: { kind: string; detail: Record<string, unknown> }[] = [];
287	    const fetchImpl: typeof fetch = async (input, init) => {
288	      const request = new Request(input, init);
289	      const url = new URL(request.url);
290	      const body = init?.body ? JSON.parse(init.body as string) as Record<string, unknown> : null;
291	      seen.push({ method: request.method, url: request.url, body });
292	      if (url.host === "api.call-e.test") {
293	        if (options.callThrows) throw new Error("network down");
294	        if (options.callStatus && options.callStatus >= 400) {
295	          return new Response(null, { status: options.callStatus });
296	        }
297	        return Response.json(options.call ?? { id: CALL, status: "in_progress" });
298	      }
299	      if (url.host === "orma-api.test" && url.pathname === "/rest/v1/call_runs") {
300	        if (request.method === "GET") {
301	          return Response.json([{ calle_call_id: CALL, dispatched_at: NOW.toISOString(), poll_after: null, created_at: NOW.toISOString(), ...options.run }]);
302	        }
303	        if (request.method === "PATCH") {
304	          return Response.json(options.patchWins === false ? [] : [{ id: options.run.id }]);
305	        }
306	      }
307	      if (url.pathname === "/rest/v1/call_events" && request.method === "POST") {
308	        events.push(body as { kind: string; detail: Record<string, unknown> });
309	        return new Response(null, { status: 201 });
310	      }
311	      throw new Error(`unexpected request ${request.method} ${request.url}`);
312	    };
313	    return { seen, events, fetchImpl };
314	  };
315	
316	  testFn("a pending call reschedules the next pass instead of finalising", async () => {
317	    const { seen, events, fetchImpl } = driver({
318	      run: { id: RUN, state: "awaiting_result" },
319	      call: { id: CALL, status: "in_progress" },
320	    });
321	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
322	    const patch = seen.find((entry) => entry.method === "PATCH");
323	    const body = patch?.body as { poll_after?: string; state?: string };
324	    if (!patch) throw new Error("a pending poll must persist the next poll time");
325	    if (body.state !== undefined) throw new Error("a pending poll must not write a terminal state");
326	    if (body.poll_after !== new Date(NOW.getTime() + POLL_INTERVAL_MS).toISOString()) {
327	      throw new Error("the next pass must be ten seconds out");
328	    }
329	    if (!seen.some((entry) => entry.method === "GET" && entry.url.includes("/v1/calls/" + CALL))) {
330	      throw new Error("a pending poll must re-fetch the authoritative call");
331	    }
332	    if (events.length !== 1 || events[0].kind !== "polled") {
333	      throw new Error("a pending poll must record exactly one polled event");
334	    }
335	  });
336	
337	  testFn("a completed call terminalises the run and leaves finalisation alone", async () => {
338	    const { seen, events, fetchImpl } = driver({
339	      run: { id: RUN, state: "dispatched" },
340	      call: { id: CALL, status: "completed", completion_confidence: { score: 0.9, label: "high" }, failure_code: null },
341	    });
342	    await pollRun({ id: RUN, state: "dispatched", poll_after: null }, depsFor(fetchImpl));
343	    const patch = seen.find((entry) => entry.method === "PATCH");
344	    const body = patch?.body as Record<string, unknown>;
345	    if (body.state !== "completed") throw new Error("a completed call must move the run to completed");
346	    if ("completed_at" in body) {
347	      throw new Error("the poll must not set completed_at, because the finaliser owns it");
348	    }
349	    if (!patch?.url.includes("state=in.%28dispatched%2Cawaiting_result%29")) {
350	      throw new Error("the terminal write must only match a still-pending run");
351	    }
352	    if (events[0]?.detail.state !== "completed" || events[0]?.detail.calle_call_id !== CALL) {
353	      throw new Error("the terminal event must name the provider id and the authoritative state");
354	    }
355	  });
356	
357	  testFn("a failed call records the failure the provider reported", async () => {
358	    const { events, fetchImpl } = driver({
359	      run: { id: RUN, state: "awaiting_result" },
360	      call: { id: CALL, status: "failed", failure_code: "no_answer", failure_message: "recipient did not pick up" },
361	    });
362	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
363	    if (events[0]?.detail.state !== "failed") throw new Error("a failed call must move the run to failed");
364	  });
365	
366	  testFn("a run the webhook already terminalised is a no-op", async () => {
367	    const { seen, events, fetchImpl } = driver({ run: { id: RUN, state: "completed" } });
368	    await pollRun({ id: RUN, state: "completed", poll_after: null }, depsFor(fetchImpl));
369	    if (seen.some((entry) => entry.url.includes("api.call-e.test"))) {
370	      throw new Error("a terminal run must not be re-fetched");
371	    }
372	    if (seen.some((entry) => entry.method === "PATCH")) {
373	      throw new Error("a terminal run must not be written");
374	    }
375	    if (events.length !== 0) throw new Error("a terminal run must record nothing");
376	  });
377	
378	  testFn("losing the race writes nothing", async () => {
379	    const { events, fetchImpl } = driver({
380	      run: { id: RUN, state: "awaiting_result" },
381	      call: { id: CALL, status: "completed" },
382	      patchWins: false,
383	    });
384	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
385	    if (events.length !== 0) {
386	      throw new Error("the loser of the race must record no timeline row");
387	    }
388	  });
389	
390	  testFn("a provider id that disagrees with the run is rejected", async () => {
391	    const { events, fetchImpl } = driver({
392	      run: { id: RUN, state: "awaiting_result" },
393	      call: { id: "call_someone_else", status: "completed" },
394	    });
395	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
396	    if (events.length !== 1 || events[0].detail.outcome !== "refetch_failed") {
397	      throw new Error("a mismatched provider id must reschedule, not terminalise");
398	    }
399	  });
400	
401	  testFn("a transport failure reschedules and never throws out of the tick", async () => {
402	    const { events, fetchImpl } = driver({
403	      run: { id: RUN, state: "awaiting_result" },
404	      callThrows: true,
405	    });
406	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
407	    if (events.length !== 1 || events[0].kind !== "polled" || events[0].detail.outcome !== "refetch_failed") {
408	      throw new Error("a transport failure must reschedule with a recorded reason");
409	    }
410	  });
411	
412	  testFn("a run past the give-up window is failed with a reason", async () => {
413	    const stale = { id: RUN, state: "awaiting_result", dispatched_at: new Date(NOW.getTime() - POLL_GIVE_UP_MS - 1).toISOString() };
414	    const { seen, events, fetchImpl } = driver({ run: stale });
415	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
416	    const patch = seen.find((entry) => entry.method === "PATCH");
417	    const body = patch?.body as { state?: string; calle_failure?: { failure_code?: string } };
418	    if (body.state !== "failed") throw new Error("a lost call must not poll forever");
419	    if (body.calle_failure?.failure_code !== "poll_timeout") {
420	      throw new Error("giving up must name the reason on the run");
421	    }
422	    if (!seen.some((entry) => entry.url.includes("api.call-e.test"))) {
423	      throw new Error("a run past its window must still ask CALL-E before giving up");
424	    }
425	    if (events[0]?.detail.failure_reason !== "poll_timeout") {
426	      throw new Error("the timeline must name where it stopped");
427	    }
428	  });
429	
430	  testFn("a run past its window that CALL-E reports completed lands as completed, not unanswered", async () => {
431	    const stale = { id: RUN, state: "awaiting_result", dispatched_at: new Date(NOW.getTime() - POLL_GIVE_UP_MS - 60_000).toISOString() };
432	    const { seen, events, fetchImpl } = driver({
433	      run: stale,
434	      call: { id: CALL, status: "completed", completion_confidence: { score: 0.9, label: "high" }, failure_code: null },
435	    });
436	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
437	    const patches = seen.filter((entry) => entry.method === "PATCH");
438	    const body = patches[0]?.body as { state?: string; disposition?: string; calle_failure?: unknown };
439	    if (patches.length !== 1 || body?.state !== "completed") {
440	      throw new Error(`an overdue call CALL-E reports completed must land as completed, saw ${JSON.stringify(patches.map((p) => p.body))}`);
441	    }
442	    if (body.disposition !== undefined || body.calle_failure !== null) {
443	      throw new Error("a completed call must not carry a give-up disposition or failure");
444	    }
445	    if (events.length !== 1 || events[0].detail.state !== "completed" || events[0].detail.outcome !== "terminal") {
446	      throw new Error(`the timeline must record the authoritative terminal state, saw ${JSON.stringify(events)}`);
447	    }
448	  });
449	
450	  testFn("a run past its window whose re-fetch fails gives up and names the re-fetch error", async () => {
451	    const stale = { id: RUN, state: "awaiting_result", dispatched_at: new Date(NOW.getTime() - POLL_GIVE_UP_MS - 60_000).toISOString() };
452	    const { seen, events, fetchImpl } = driver({ run: stale, callStatus: 503 });
