1	/**
2	 * Claims due call runs. PostgreSQL owns the claim so concurrent cron requests
3	 * cannot send the same run to CALL-E twice.
4	 *
5	 * T2.4 wires each claimed run to the guarded CALL-E dispatcher.
6	 *
7	 * Pin with: deno test --allow-env --allow-net supabase/functions/tick/index.ts
8	 */
9	
10	import { withSupabase } from "npm:@supabase/server@1.6.0";
11	import {
12	  type CalleDeps,
13	  depsFromEnv as calleDepsFromEnv,
14	  dispatchClaimedRun,
15	} from "../_shared/calle.ts";
16	import { recordCallEvent } from "../_shared/events.ts";
17	import { pollRun } from "../_shared/poll.ts";
18	
19	const CLAIM_LIMIT = 20;
20	
21	export type TickRun = {
22	  id: string;
23	  state: string;
24	  poll_after: string | null;
25	};
26	
27	export type ClaimedTickRun = TickRun & {
28	  user_id: string;
29	  idempotency_key: string;
30	  slot_id: string | null;
31	  /** The claim RPC returns the whole row, so dry mode is decided per run. */
32	  dry_run: boolean;
33	};
34	
35	export type TickDeps = {
36	  apiUrl: string;
37	  serviceRoleKey: string;
38	  fetch: typeof fetch;
39	  dispatchClaimed?: (run: ClaimedTickRun) => Promise<void>;
40	  /** Resolves false, or throws, when the pass did not land. */
41	  pollDue: (run: TickRun) => Promise<boolean | void>;
42	  finalise: (run: TickRun) => Promise<void>;
43	  now: () => Date;
44	};
45	
46	export type TickResult = {
47	  claimed: number;
48	  polled: number;
49	  finalised: number;
50	};
51	
52	export function requireNamedEnv(
53	  name: string,
54	  getEnv: (key: string) => string | undefined = (key) => Deno.env.get(key),
55	): string {
56	  const value = getEnv(name);
57	  if (!value) throw new Error(`missing ${name}`);
58	  return value;
59	}
60	
61	function unavailable(stage: string): (run: TickRun) => Promise<void> {
62	  return async () => {
63	    throw new Error(`${stage} implementation is unavailable`);
64	  };
65	}
66	
67	/**
68	 * One run's poll pass, isolated from the rest. A write that fails leaves the
69	 * run's `poll_after` untouched, so the next tick retries it. One broken run
70	 * must never cost every other run in the same tick.
71	 */
72	export async function pollStep(
73	  run: TickRun,
74	  calleDeps: CalleDeps,
75	): Promise<boolean> {
76	  try {
77	    await pollRun(run, calleDeps);
78	    return true;
79	  } catch (error) {
80	    console.error(
81	      `poll failed for run ${run.id}`,
82	      error instanceof Error ? error.message : "unknown error",
83	    );
84	    return false;
85	  }
86	}
87	
88	/**
89	 * Runs one step per run in isolation and counts only the steps that landed.
90	 * A step fails when it throws or reports false, and the tick then must not
91	 * claim it in the response body.
92	 */
93	async function countSucceeded(
94	  runs: TickRun[],
95	  step: (run: TickRun) => Promise<boolean | void>,
96	  stage: string,
97	): Promise<number> {
98	  const results = await Promise.all(runs.map(async (run) => {
99	    try {
100	      return await step(run) !== false;
101	    } catch (error) {
102	      console.error(
103	        `${stage} failed for run ${run.id}`,
104	        error instanceof Error ? error.message : "unknown error",
105	      );
106	      return false;
107	    }
108	  }));
109	  return results.filter(Boolean).length;
110	}
111	
112	export function depsFromEnv(
113	  getEnv: (key: string) => string | undefined = (key) => Deno.env.get(key),
114	  fetchImpl: typeof fetch = fetch,
115	): TickDeps {
116	  const calleDeps = calleDepsFromEnv(getEnv, fetchImpl);
117	  return {
118	    apiUrl: requireNamedEnv("ORMA_API_URL", getEnv),
119	    serviceRoleKey: requireNamedEnv("SUPABASE_SERVICE_ROLE_KEY", getEnv),
120	    fetch: fetchImpl,
121	    dispatchClaimed: (run) => dispatchClaimedRun(run, calleDeps),
122	    pollDue: (run) => pollStep(run, calleDeps),
123	    finalise: unavailable("finalisation"),
124	    now: () => new Date(),
125	  };
126	}
127	
128	function serviceHeaders(key: string): HeadersInit {
129	  return {
130	    apikey: key,
131	    authorization: `Bearer ${key}`,
132	    "content-type": "application/json",
133	  };
134	}
135	
136	function restUrl(base: string, path: string, query = ""): string {
137	  return `${base.replace(/\/+$/, "")}/rest/v1/${path}${
138	    query ? `?${query}` : ""
139	  }`;
140	}
141	
142	async function readRows(
143	  deps: TickDeps,
144	  query: URLSearchParams,
145	): Promise<TickRun[]> {
146	  const response = await deps.fetch(
147	    restUrl(deps.apiUrl, "call_runs", query.toString()),
148	    {
149	      headers: serviceHeaders(deps.serviceRoleKey),
150	    },
151	  );
152	  if (!response.ok) throw new Error("call_runs read failed");
153	  return await response.json() as TickRun[];
154	}
155	
156	/** Calls the only SQL boundary allowed to claim runs. Do not replace this with
157	 * a REST PATCH: PostgREST cannot provide a `FOR UPDATE SKIP LOCKED` claim.
158	 */
159	export async function claimDueRuns(deps: TickDeps): Promise<ClaimedTickRun[]> {
160	  const response = await deps.fetch(
161	    restUrl(deps.apiUrl, "rpc/claim_due_call_runs"),
162	    {
163	      method: "POST",
164	      headers: serviceHeaders(deps.serviceRoleKey),
165	      body: JSON.stringify({ p_limit: CLAIM_LIMIT }),
166	    },
167	  );
168	  if (!response.ok) throw new Error("due call_runs claim failed");
169	  return await response.json() as ClaimedTickRun[];
170	}
171	
172	export async function duePolls(deps: TickDeps): Promise<TickRun[]> {
173	  const query = new URLSearchParams({
174	    select: "id,state,poll_after",
175	    state: "in.(dispatched,awaiting_result)",
176	    poll_after: `lte.${deps.now().toISOString()}`,
177	    order: "poll_after",
178	    limit: String(CLAIM_LIMIT),
179	  });
180	  return readRows(deps, query);
181	}
182	
183	export async function terminalRuns(deps: TickDeps): Promise<TickRun[]> {
184	  const query = new URLSearchParams({
185	    select: "id,state,poll_after",
186	    state: "in.(completed,no_result,failed,canceled)",
187	    completed_at: "is.null",
188	    order: "scheduled_for",
189	    limit: String(CLAIM_LIMIT),
190	  });
191	  return readRows(deps, query);
192	}
193	
194	export async function tick(deps: TickDeps): Promise<TickResult> {
195	  const claimed = deps.dispatchClaimed ? await claimDueRuns(deps) : [];
196	  if (deps.dispatchClaimed) {
197	    await Promise.all(claimed.map(async (run) => {
198	      await recordCallEvent(run.id, "claimed", { state: run.state }, deps);
199	      await deps.dispatchClaimed!(run);
200	    }));
201	  }
202	
203	  const polls = await duePolls(deps);
204	  const polled = await countSucceeded(polls, deps.pollDue, "poll");
205	
206	  const terminal = await terminalRuns(deps);
207	  // Each run finalises in isolation, like pollStep. One run that cannot
208	  // finalise stays selected for the next tick and costs its siblings nothing.
209	  const finalised = await countSucceeded(terminal, deps.finalise, "finalise");
210	
211	  return { claimed: claimed.length, polled, finalised };
212	}
213	
214	export function createTickHandler(
215	  deps: TickDeps,
216	): (request: Request) => Promise<Response> {
217	  return async (request) => {
218	    if (request.method !== "POST") {
219	      return new Response(null, { status: 405, headers: { allow: "POST" } });
220	    }
221	    try {
222	      return Response.json(await tick(deps));
223	    } catch (error) {
224	      console.error(
225	        "tick failed",
226	        error instanceof Error ? error.message : "unknown error",
227	      );
228	      return new Response(null, { status: 500 });
229	    }
230	  };
231	}
