154	/** Returns true when the event id was already recorded, which marks a redelivery. */
155	async function insertPendingEvent(deps: WebhookDeps, eventId: string): Promise<boolean> {
156	  const response = await deps.fetch(restUrl(deps.apiUrl, "webhook_events"), {
157	    method: "POST",
158	    headers: serviceHeaders(deps.serviceRoleKey, "return=minimal"),
159	    body: JSON.stringify({ event_id: eventId, type: PENDING }),
160	  });
161	  if (response.status === 409) return true;
162	  if (!response.ok) throw new Error("webhook event record failed");
163	  return false;
164	}
165	
166	async function claimPendingEvent(deps: WebhookDeps, eventId: string, now = Date.now()): Promise<boolean> {
167	  const staleBefore = new Date(now - REFRESH_LEASE_MS).toISOString();
168	  const query = new URLSearchParams({
169	    event_id: `eq.${eventId}`,
170	    or: `(type.eq.${PENDING},and(type.eq.${REFRESHING},received_at.lt.${staleBefore}))`,
171	  });
172	  const response = await deps.fetch(restUrl(deps.apiUrl, "webhook_events", query.toString()), {
173	    method: "PATCH",
174	    headers: serviceHeaders(deps.serviceRoleKey, "return=representation"),
175	    body: JSON.stringify({ type: REFRESHING, received_at: new Date(now).toISOString() }),
176	  });
177	  if (!response.ok) throw new Error("webhook event claim failed");
178	  const rows: unknown = await response.json();
179	  return Array.isArray(rows) && rows.length === 1;
180	}
181	
182	async function setEventState(deps: WebhookDeps, eventId: string, type: string): Promise<void> {
183	  const query = new URLSearchParams({ event_id: `eq.${eventId}`, type: `eq.${REFRESHING}` });
184	  const response = await deps.fetch(restUrl(deps.apiUrl, "webhook_events", query.toString()), {
185	    method: "PATCH",
186	    headers: serviceHeaders(deps.serviceRoleKey, "return=minimal"),
187	    body: JSON.stringify({ type }),
188	  });
189	  if (!response.ok) throw new Error("webhook event state update failed");
190	}
