279	export function createWebhookHandler(deps: WebhookDeps): (request: Request) => Promise<Response> {
280	  return async (request) => {
281	    if (request.method !== "POST") {
282	      return new Response(null, { status: 405, headers: { allow: "POST" } });
283	    }
284	    const presented = presentedWebhookSecret(new URL(request.url).pathname);
285	    if (!presented || !webhookSecretsMatch(presented, deps.webhookSecret)) {
286	      return new Response(null, { status: 401 });
287	    }
288	    const headerEventId = request.headers.get(EVENT_ID_HEADER);
289	    if (!headerEventId) return new Response(null, { status: 400 });
290	    try {
291	      const body = await request.text();
292	      if (new TextEncoder().encode(body).byteLength > MAX_BODY_BYTES) {
293	        return new Response(null, { status: 413 });
294	      }
295	      const envelope = parseWebhookEnvelope(body, headerEventId);
296	      if (!envelope) return new Response(null, { status: 400 });
297	      const redelivered = await insertPendingEvent(deps, envelope.id);
298	      if (!await claimPendingEvent(deps, envelope.id)) return new Response(null, { status: 200 });
299	      try {
300	        const call = await fetchAuthoritativeCall(deps, envelope.data.id);
301	        if (!call || !await hasMatchingOrmaRun(deps, call)) {
302	          await setEventState(deps, envelope.id, IGNORED);
303	          return new Response(null, { status: 200 });
304	        }
305	        // Persist the transition before the timeline claims it, so a failed
306	        // write never leaves an entry asserting a state that never landed.
307	        // The event row is released to pending below, so this is retried.
308	        const outcome = await terminaliseFromRefetch(deps, call, redelivered);
309	        const eventDeps = { apiUrl: deps.apiUrl, serviceRoleKey: deps.serviceRoleKey, fetch: deps.fetch };
310	        await recordCallEvent(
311	          call.metadata.call_run_id,
312	          "webhook_received",
313	          { calle_call_id: call.id, event_type: envelope.type },
314	          eventDeps,
315	        );
316	        await recordCallEvent(
317	          call.metadata.call_run_id,
318	          "refetched",
319	          { calle_call_id: call.id, event_type: envelope.type, state: call.status, outcome },
320	          eventDeps,
321	        );
322	        await setEventState(deps, envelope.id, REFETCHED);
323	        return new Response(null, { status: 200 });
324	      } catch (error) {
325	        try {
326	          await setEventState(deps, envelope.id, PENDING);
327	        } catch (releaseError) {
328	          console.error("calle webhook event release failed", releaseError instanceof Error ? releaseError.message : "unknown error");
329	        }
330	        throw error;
331	      }
332	    } catch (error) {
333	      console.error("calle webhook re-fetch failed", error instanceof Error ? error.message : "unknown error");
334	      return new Response(null, { status: 500 });
335	    }
336	  };
337	}
