  const c = `call_rem2_a3_${tag}`;
  const id = await createRun("A3-overdue-refetch-fails", { state: "awaiting_result", dispatched_at: ago(POLL_GIVE_UP_MS + 60_000), poll_after: ago(1_000) }, c);
  fakes.set(c, { status: "completed", httpStatus: 503 });
  await pollRun({ id, state: "awaiting_result", poll_after: null }, calleDepsFromEnv(env, stub));
  console.log(`A3-refetches-by-poll=${refetches.get(c) ?? 0}`);
}

if (mode === "B") {
