  const c = `call_rem2_b_${tag}`;
  await createRun("B-retried", { state: "awaiting_result", dispatched_at: ago(90_000), poll_after: new Date(Date.now() + 3_600_000).toISOString() }, c);
  fakes.set(c, { status: "completed" });
  let failed = false;
