  };
  const eventId = `evt_rem2_b_${tag}`;
  console.log(`B-first-delivery-status=${await deliver(c, eventId, flaky)}`);
  console.log(`B-redelivery-status=${await deliver(c, eventId, flaky)}`);
}

if (mode === "B2") {
  // Regression. The first delivery fails on re-fetch, the poll moves the run, then
  // the redelivery must still say the poll resolved it.
