  const id = await createRun("B2-poll-between", { state: "awaiting_result", dispatched_at: ago(90_000), poll_after: ago(1_000) }, c);
  fakes.set(c, { status: "completed", httpStatus: 503 });
  const eventId = `evt_rem2_b2_${tag}`;
  console.log(`B2-first-delivery-status=${await deliver(c, eventId)}`);
  fakes.set(c, { status: "completed" });
  await pollRun({ id, state: "awaiting_result", poll_after: null }, calleDepsFromEnv(env, stub));
  console.log(`B2-redelivery-status=${await deliver(c, eventId)}`);
}

if (mode === "T") {
