/**
 * T2.5 review round 3 live pins. Drives the real tick handler, webhook handler,
 * pollRun, fetchCall and ingestTerminalRun from ROOT (default: the frozen copy)
 * against the scratch stack. Only the CALL-E transport is a stub. Every claim is
 * a separate psql read scoped to idempotency_key like 'rev3-t25-%'.
 */
const ROOT = Deno.env.get("ROOT") ?? "/tmp/orma-review-t25-r3";
const { createTickHandler, depsFromEnv: tickDepsFromEnv } = await import(`${ROOT}/supabase/functions/tick/index.ts`);
const { createWebhookHandler, depsFromEnv: webhookDepsFromEnv } = await import(`${ROOT}/supabase/functions/calle-webhook/index.ts`);
const { depsFromEnv: calleDepsFromEnv } = await import(`${ROOT}/supabase/functions/_shared/calle.ts`);
const { pollRun, fetchCall, POLL_GIVE_UP_MS } = await import(`${ROOT}/supabase/functions/_shared/poll.ts`);
const { ingestTerminalRun } = await import(`${ROOT}/supabase/functions/_shared/ingest.ts`);

const API = Deno.env.get("ORMA_API_URL")!;
const KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const SECRET = Deno.env.get("ORMA_WEBHOOK_SECRET")!;
const USER = "00000000-0000-4000-8000-000000000001";
if (Deno.env.get("CALLE_API_BASE") !== "https://api.call-e.test") throw new Error("refusing: CALLE_API_BASE is not the stub host");

const headers = { apikey: KEY, authorization: `Bearer ${KEY}`, "content-type": "application/json" };
const rest = (path: string, init: RequestInit = {}) =>
  fetch(`${API}/rest/v1/${path}`, { ...init, headers: { ...headers, ...(init.headers ?? {}) } });
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

type Fake = { status: string; delayMs?: number; httpStatus?: number; body?: Record<string, unknown> };
const fakes = new Map<string, Fake>();
const runByCall = new Map<string, string>();
const refetches = new Map<string, number>();
const stub: typeof fetch = async (input, init) => {
  const request = new Request(input, init);
  const url = new URL(request.url);
  if (url.host === "api.call-e.test") {
    if (request.method !== "GET") return new Response(null, { status: 599 });
    const id = url.pathname.split("/").pop()!;
    const fake = fakes.get(id);
    if (!fake) return new Response(null, { status: 404 });
    if (fake.delayMs) await sleep(fake.delayMs);
    refetches.set(id, (refetches.get(id) ?? 0) + 1);
    if (fake.httpStatus) return new Response(null, { status: fake.httpStatus });
    return Response.json({
      completion_confidence: null, failure_code: null, ...(fake.body ?? {}),
      id, status: fake.status, metadata: { call_run_id: runByCall.get(id) },
    });
  }
  if (url.origin !== new URL(API).origin) throw new Error(`refusing outbound request to ${url.host}`);
  return await fetch(request);
};
const env = (k: string) => Deno.env.get(k);

async function guardForeignRows(): Promise<void> {
  const response = await rest(
    "call_runs?select=id&idempotency_key=not.like.rev3-t25-*&or=(state.in.(scheduled,claimed,dispatched,awaiting_result),and(state.in.(completed,no_result,failed,canceled),completed_at.is.null))",
  );
  const foreign = await response.json() as unknown[];
  if (!Array.isArray(foreign) || foreign.length !== 0) {
    throw new Error(`refusing to tick: foreign rows are claimable, pollable or finalisable: ${JSON.stringify(foreign)}`);
  }
}

async function createRun(label: string, patch: Record<string, unknown>, callId: string | null): Promise<string> {
  const id = crypto.randomUUID();
  if (callId) runByCall.set(callId, id);
  const response = await rest("call_runs", {
    method: "POST",
    body: JSON.stringify({
      id, user_id: USER, local_date: "2026-09-13", part_of_day: `rev3-${label}`,
      scheduled_for: new Date().toISOString(), idempotency_key: `rev3-t25-${label}-${id}`,
      calle_call_id: callId, ...patch,
    }),
  });
  if (!response.ok) throw new Error(`create ${label} failed ${response.status} ${await response.text()}`);
  console.log(`${label}=${id}`);
  return id;
}

async function deliver(callId: string, eventId: string, fetchImpl: typeof fetch = stub, type = "call.completed"): Promise<number> {
  const envelope = { id: eventId, type, created_at: new Date().toISOString(), data: { id: callId } };
  const response = await createWebhookHandler(webhookDepsFromEnv(env, fetchImpl))(
    new Request(`${API}/functions/v1/calle-webhook/${SECRET}`, {
      method: "POST", headers: { "call-e-event-id": eventId }, body: JSON.stringify(envelope),
    }),
  );
  return response.status;
}

const mode = Deno.args[0];
const tag = crypto.randomUUID().slice(0, 6);
const ago = (ms: number) => new Date(Date.now() - ms).toISOString();
const later = (ms: number) => new Date(Date.now() + ms).toISOString();
const poll = (id: string, f: typeof fetch = stub) =>
  pollRun({ id, state: "awaiting_result", poll_after: null }, calleDepsFromEnv(env, f));

if (mode === "T") {
  // Round 1 H and round 2 second L. The finalise stub throws, the sibling poll lands.
  const t = `call_rev3_tterm_${tag}`, s = `call_rev3_tsib_${tag}`;
  await createRun("T-terminal", { state: "completed", dispatched_at: ago(180_000) }, t);
  await createRun("T-sibling", { state: "awaiting_result", dispatched_at: ago(120_000), poll_after: ago(1_000) }, s);
  fakes.set(s, { status: "completed" });
  await guardForeignRows();
  const response = await createTickHandler(tickDepsFromEnv(env, stub))(new Request(`${API}/functions/v1/tick`, { method: "POST" }));
  console.log(`T-tick-status=${response.status} body=${await response.text()}`);
}

if (mode === "M") {
  // Round 1 M. No dispatched_at, created_at past the window, poll_after sliding.
  const c = `call_rev3_m_${tag}`;
  const id = await createRun("M-no-dispatched-at", { state: "awaiting_result", dispatched_at: null, created_at: ago(POLL_GIVE_UP_MS + 120_000), poll_after: ago(1_000) }, c);
  fakes.set(c, { status: "in_progress" });
  await poll(id);
  console.log(`M-refetches=${refetches.get(c) ?? 0}`);
}

if (mode === "L") {
  // Round 1 L. The poll wins, the late webhook re-fetches failed.
  const c = `call_rev3_l_${tag}`;
  const id = await createRun("L-poll-wins", { state: "awaiting_result", dispatched_at: ago(90_000), poll_after: ago(1_000) }, c);
  fakes.set(c, { status: "completed" });
  await poll(id);
  fakes.set(c, { status: "failed" });
  console.log(`L-webhook-status=${await deliver(c, `evt_rev3_l_${tag}`, stub, "call.failed")}`);
}

if (mode === "A") {
  // Round 2 H. Overdue, CALL-E reports completed.
  const c = `call_rev3_a_${tag}`;
  const id = await createRun("A-overdue-completed", { state: "awaiting_result", dispatched_at: ago(POLL_GIVE_UP_MS + 60_000), poll_after: ago(1_000) }, c);
  fakes.set(c, { status: "completed" });
  await poll(id);
  console.log(`A-refetches=${refetches.get(c) ?? 0}`);
}

if (mode === "B") {
  // Round 2 first L. The webhook's own write lands, then its first timeline insert fails once.
  const c = `call_rev3_b_${tag}`;
  await createRun("B-retried", { state: "awaiting_result", dispatched_at: ago(90_000), poll_after: later(3_600_000) }, c);
  fakes.set(c, { status: "completed" });
  let failed = false;
  const flaky: typeof fetch = async (input, init) => {
    const request = new Request(input, init);
    if (!failed && request.method === "POST" && new URL(request.url).pathname.endsWith("/call_events")) {
      failed = true;
      return new Response(null, { status: 503 });
    }
    return await stub(request);
  };
  const eventId = `evt_rev3_b_${tag}`;
  console.log(`B-first=${await deliver(c, eventId, flaky)} B-redelivery=${await deliver(c, eventId, flaky)}`);
}

if (mode === "F1a") {
  // New. Two distinct terminal events for one call. Event 1 applies. Event 2's first
  // attempt fails on its re-fetch, so its retry arrives as a 409 redelivery.
  const c = `call_rev3_f1a_${tag}`;
  await createRun("F1a-two-events", { state: "awaiting_result", dispatched_at: ago(90_000), poll_after: later(3_600_000) }, c);
  fakes.set(c, { status: "completed" });
  console.log(`F1a-event1=${await deliver(c, `evt_rev3_f1a_one_${tag}`)}`);
  fakes.set(c, { status: "completed", httpStatus: 503 });
  console.log(`F1a-event2-first=${await deliver(c, `evt_rev3_f1a_two_${tag}`, stub, "call.result_validation_failed")}`);
  fakes.set(c, { status: "completed" });
  console.log(`F1a-event2-redelivery=${await deliver(c, `evt_rev3_f1a_two_${tag}`, stub, "call.result_validation_failed")}`);
}

if (mode === "F1b") {
  // New, the remediator's open item. The webhook's first attempt fails on re-fetch.
  // The poll then moves the run, and its polled insert fails. The redelivery follows.
  const c = `call_rev3_f1b_${tag}`;
  const id = await createRun("F1b-poll-row-lost", { state: "awaiting_result", dispatched_at: ago(90_000), poll_after: ago(1_000) }, c);
  const eventId = `evt_rev3_f1b_${tag}`;
  fakes.set(c, { status: "completed", httpStatus: 503 });
  console.log(`F1b-first=${await deliver(c, eventId)}`);
  fakes.set(c, { status: "completed" });
  const eventsDown: typeof fetch = async (input, init) => {
    const request = new Request(input, init);
    if (request.method === "POST" && new URL(request.url).pathname.endsWith("/call_events")) return new Response("{}", { status: 503 });
    return await stub(request);
  };
  try {
    await poll(id, eventsDown);
    console.log("F1b-poll=resolved");
  } catch (error) {
    console.log(`F1b-poll=threw ${(error as Error).message}`);
  }
  console.log(`F1b-redelivery=${await deliver(c, eventId)}`);
}

if (mode === "F1c") {
  // New. The redelivery races a healthy poll. The poll's PATCH lands first, and the
  // redelivery reads call_events before the poll's polled row is inserted.
  for (let round = 1; round <= 3; round++) {
    const c = `call_rev3_f1c_${round}_${tag}`;
    const id = await createRun(`F1c-race-${round}`, { state: "awaiting_result", dispatched_at: ago(90_000), poll_after: ago(1_000) }, c);
    const eventId = `evt_rev3_f1c_${round}_${tag}`;
    fakes.set(c, { status: "completed", httpStatus: 503 });
    const first = await deliver(c, eventId);
    fakes.set(c, { status: "completed" });
    const slowEvents: typeof fetch = async (input, init) => {
      const request = new Request(input, init);
      if (request.method === "POST" && new URL(request.url).pathname.endsWith("/call_events")) await sleep(600);
      return await stub(request);
    };
    const slowRefetch: typeof fetch = async (input, init) => {
      const request = new Request(input, init);
      if (new URL(request.url).host === "api.call-e.test") await sleep(200);
      return await stub(request);
    };
    const [, status] = await Promise.all([poll(id, slowEvents), deliver(c, eventId, slowRefetch)]);
    console.log(`F1c-${round} first=${first} redelivery=${status}`);
  }
}

if (mode === "F2") {
  // New. Overdue run, one failed re-fetch, poll gives up. The finaliser as T2.7a
  // specifies it then re-fetches and ingests the call CALL-E reports completed.
  const c = `call_rev3_f2_${tag}`;
  const id = await createRun("F2-giveup-then-finalise", { state: "awaiting_result", dispatched_at: ago(POLL_GIVE_UP_MS + 60_000), poll_after: ago(1_000) }, c);
  fakes.set(c, { status: "completed", httpStatus: 503 });
  await poll(id);
  console.log("F2-after-poll");
  const fixture = JSON.parse(await Deno.readTextFile(`${ROOT}/testdata/calle/call-completed.json`));
  fakes.set(c, { status: "completed", body: { ...fixture, failure_code: null, failure_message: null } });
  const call = await fetchCall(c, calleDepsFromEnv(env, stub)) as Record<string, unknown>;
  const attempts = (call.attempts as { transcript_turns?: unknown[] }[] | undefined) ?? [];
  const result = await ingestTerminalRun({
    callRunId: id, userId: USER, raw: call,
    transcriptTurns: (attempts[0]?.transcript_turns ?? []) as never, structuredResult: null,
  }, { apiUrl: API, serviceRoleKey: KEY, fetch: stub });
  console.log(`F2-ingest disposition=${result.disposition} already=${result.alreadyIngested}`);
}

