  // Exactly one winner. RO makes the run overdue, so the poll's pending re-fetch
  // gives up while the webhook's re-fetch reports completed.
  const overdue = mode === "RO";
  for (const order of ["poll-first", "webhook-first"]) {
    for (let round = 1; round <= 3; round++) {
      const c = `call_rev3_${mode}_${order}_${round}_${tag}`;
      const id = await createRun(`${mode}-${order}-${round}`, {
        state: "awaiting_result", poll_after: ago(1_000),
        dispatched_at: overdue ? ago(POLL_GIVE_UP_MS + 60_000) : ago(90_000),
      }, c);
      fakes.set(c, { status: overdue ? "in_progress" : "completed" });
      const pollStub: typeof fetch = async (input, init) => {
        const request = new Request(input, init);
        if (order === "webhook-first" && new URL(request.url).host === "api.call-e.test") await sleep(150);
        return await stub(request);
      };
      const hookStub: typeof fetch = async (input, init) => {
        const request = new Request(input, init);
        if (new URL(request.url).host === "api.call-e.test") {
          const body = await (await stub(request)).json();
          body.status = overdue ? "completed" : "failed";
          if (order === "poll-first") await sleep(150);
          return Response.json(body);
        }
        return await stub(request);
      };
      const [, status] = await Promise.all([
        poll(id, pollStub),
        deliver(c, `evt_rev3_${mode}_${order}_${round}_${tag}`, hookStub, overdue ? "call.completed" : "call.failed"),
      ]);
      console.log(`${mode}-${order}-${round} webhook=${status}`);
    }
  }
}

